#include <bits/stdc++.h>
using namespace std;

static int n, t;

struct Room {
    int i, j;
    array<bool, 61> infected;
    array<bool, 61> accessible;
    int scientists, capsules;

    Room() : scientists(0), capsules(0) {
        infected.fill(false);
        accessible.fill(true);
    }

    int get_node_id(int timestamp) const {
        return 2 + i + n * j + (n * n) * timestamp;
    }

    void set_reactor() {
        accessible.fill(false);
    }

    void set_infected(int timestamp = 0) {
        if (accessible[timestamp]) {
            accessible[timestamp] = false;
            infected[timestamp] = true;
        }
    }

    void spread_infection(int timestamp);
};

static array<array<Room, 10>, 10> floorplan;

void Room::spread_infection(int timestamp) {
    if (!infected[timestamp]) return;
    set_infected(timestamp + 1);

    if (i > 0) floorplan[i - 1][j].set_infected(timestamp + 1);
    if (i < n - 1) floorplan[i + 1][j].set_infected(timestamp + 1);
    if (j > 0) floorplan[i][j - 1].set_infected(timestamp + 1);
    if (j < n - 1) floorplan[i][j + 1].set_infected(timestamp + 1);
}

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };

    int N;
    vector<vector<Edge>> g;
    vector<int> level, ptr;

    Dinic(int n) : N(n), g(n), level(n), ptr(n) {}

    void add_edge(int v, int to, int cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0};
        g[v].push_back(a);
        g[to].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (const Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }

        return level[t] != -1;
    }

    int dfs(int v, int t, int pushed) {
        if (v == t) return pushed;

        for (int &cid = ptr[v]; cid < (int)g[v].size(); cid++) {
            Edge &e = g[v][cid];

            if (e.cap > 0 && level[e.to] == level[v] + 1) {
                int tr = dfs(e.to, t, min(pushed, e.cap));
                if (tr == 0) continue;

                e.cap -= tr;
                g[e.to][e.rev].cap += tr;
                return tr;
            }
        }

        return 0;
    }

    int max_flow(int s, int t) {
        int flow = 0;

        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);

            while (true) {
                int pushed = dfs(s, t, INT_MAX);
                if (!pushed) break;
                flow += pushed;
            }
        }

        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);

    cin >> n >> t;

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            floorplan[i][j].i = i;
            floorplan[i][j].j = j;

            if (line[j] == 'Y') floorplan[i][j].set_reactor();
            else if (line[j] == 'Z') floorplan[i][j].set_infected();
            else floorplan[i][j].scientists = line[j] - '0';
        }
    }

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                floorplan[i][j].capsules = line[j] - '0';
            }
        }
    }

    for (int c = 0; c <= t; c++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (c < t) floorplan[i][j].spread_infection(c);
            }
        }
    }

    Dinic mf(n * n * (t + 1) + 2);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            const Room &room = floorplan[i][j];

            if (room.scientists > 0) {
                mf.add_edge(0, room.get_node_id(0), room.scientists);
            }

            if (room.capsules > 0) {
                mf.add_edge(room.get_node_id(t), 1, room.capsules);
            }

            for (int c = 0; c < t; c++) {
                if (room.capsules > 0) {
                    mf.add_edge(room.get_node_id(c), room.get_node_id(t), 1000);
                }

                if (!room.accessible[c]) continue;

                if (i > 0 && floorplan[i - 1][j].accessible[c]) {
                    mf.add_edge(room.get_node_id(c), floorplan[i - 1][j].get_node_id(c + 1), 1000);
                }

                if (i < n - 1 && floorplan[i + 1][j].accessible[c]) {
                    mf.add_edge(room.get_node_id(c), floorplan[i + 1][j].get_node_id(c + 1), 1000);
                }

                if (j > 0 && floorplan[i][j - 1].accessible[c]) {
